import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Dashboard.css';
import coachDefaultImage from '../../images/coach.png';

const Dashboard = () => {
  const [coaches, setCoaches] = useState([]);
  const [filteredCoaches, setFilteredCoaches] = useState([]);
  const [trainerInfo, setTrainerInfo] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    profilePicture: coachDefaultImage,
    experience: ''
  });
  const [editingCoach, setEditingCoach] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [experienceFilter, setExperienceFilter] = useState('');
  
  const [gymStats] = useState({
    totalMembers: 150,
    activeMembers: 120,
    upcomingSessions: 5,
    totalClasses: 10,
  });

  const [upcomingClasses] = useState([
    { id: 1, time: '9:00 AM', className: 'Yoga for Beginners', location: 'Studio A' },
    { id: 2, time: '11:00 AM', className: 'HIIT Workout', location: 'Studio B' },
    { id: 3, time: '1:00 PM', className: 'Strength Training', location: 'Gym Floor' },
  ]);

  // Filter coaches based on search term and experience
  useEffect(() => {
    let result = coaches;
    if (searchTerm) {
      result = result.filter(coach => 
        coach.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        coach.email.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }
    if (experienceFilter) {
      result = result.filter(coach => 
        coach.experience && coach.experience.toString().includes(experienceFilter)
      );
    }
    setFilteredCoaches(result);
  }, [searchTerm, experienceFilter, coaches]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleCoachChange = (e) => {
    setEditingCoach({ ...editingCoach, [e.target.name]: e.target.value });
  };

  const toggleEdit = async () => {
    if (isEditing) {
      try {
        const response = await axios.put('http://localhost:5000/api/coach/profile', formData, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });
        setTrainerInfo(response.data);
      } catch (error) {
        console.error('Error updating profile:', error);
      }
    }
    setIsEditing(!isEditing);
  };

  const deleteProfile = async () => {
    if (window.confirm('Are you sure you want to delete your profile?')) {
      try {
        await axios.delete('http://localhost:5000/api/coach/profile', {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        });
        setTrainerInfo(null);
      } catch (error) {
        console.error('Error deleting profile:', error);
      }
    }
  };

  const startEditCoach = (coach) => {
    setEditingCoach({ 
      ...coach,
      profilePicture: coach.profilePicture || coachDefaultImage
    });
  };

  const cancelEditCoach = () => {
    setEditingCoach(null);
  };

  const saveCoach = async () => {
    try {
      const { _id, ...coachData } = editingCoach;
      await axios.put(`http://localhost:5000/api/coach/${_id}`, coachData);
      fetchCoaches();
      setEditingCoach(null);
    } catch (error) {
      console.error('Error updating coach:', error);
    }
  };

  const deleteCoach = async (id) => {
    if (window.confirm('Are you sure you want to delete this coach?')) {
      try {
        await axios.delete(`http://localhost:5000/api/coach/${id}`);
        setCoaches(coaches.filter(coach => coach._id !== id));
      } catch (error) {
        console.error('Error deleting coach:', error);
      }
    }
  };

  const fetchCoaches = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/coach');
      setCoaches(response.data);
      setFilteredCoaches(response.data);
    } catch (error) {
      console.error('Error fetching coaches:', error);
    }
  };

  return (
    <div className="dashboard-container">
      {/* Full-width header */}
      <header className="dashboard-header">
        <div className="header-content">
          <h2>Welcome, {trainerInfo ? `Coach ${trainerInfo.name}` : 'Guest'}!</h2>
          <p>Manage gym activities, check stats, and view upcoming classes.</p>
        </div>
      </header>

      <div className="dashboard-content">
        {/* Stats Cards Row */}
        <div className="stats-row">
          <div className="stat-card">
            <h3>Total Members</h3>
            <p>{gymStats.totalMembers}</p>
          </div>
          <div className="stat-card">
            <h3>Active Members</h3>
            <p>{gymStats.activeMembers}</p>
          </div>
          <div className="stat-card">
            <h3>Total Classes</h3>
            <p>{gymStats.totalClasses}</p>
          </div>
          <div className="stat-card">
            <h3>Upcoming Sessions</h3>
            <p>{gymStats.upcomingSessions}</p>
          </div>
        </div>

        <div className="main-dashboard-content">
          {/* Left Side - All Coaches */}
          <div className="coaches-section">
            <div className="coaches-header">
              <h3>All Coaches</h3>
              <div className="search-filter-container">
                <input
                  type="text"
                  placeholder="Search coaches..."
                  className="search-input"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
                <input
                  type="number"
                  placeholder="Filter by experience (years)"
                  className="filter-input"
                  value={experienceFilter}
                  onChange={(e) => setExperienceFilter(e.target.value)}
                  min="0"
                />
              </div>
            </div>
            <div className="coaches-grid">
              {filteredCoaches.map((coach) => (
                <div key={coach._id} className="coach-card">
                  <div className="coach-image-wrapper">
                    <img 
                      src={coach.profilePicture || coachDefaultImage} 
                      alt={coach.name} 
                      className="coach-image" 
                    />
                  </div>
                  <div className="coach-details">
                    <h4>{coach.name}</h4>
                    <p><strong>Email:</strong> {coach.email}</p>
                    {coach.experience && <p><strong>Experience:</strong> {coach.experience} years</p>}
                  </div>
                  <div className="coach-card-actions">
                    <button onClick={() => startEditCoach(coach)} className="edit-btn">Edit</button>
                    <button onClick={() => deleteCoach(coach._id)} className="delete-btn">Delete</button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Right Side - Upcoming Classes and Profile */}
          <div className="right-panel">
            {/* Upcoming Classes */}
            <div className="upcoming-classes">
              <div className="classes-card">
                <h3>Upcoming Classes</h3>
                <ul>
                  {upcomingClasses.map((classItem) => (
                    <li key={classItem.id}>
                      <strong>{classItem.className}</strong>
                      <div className="class-details">
                        <span>{classItem.time}</span>
                        <span>{classItem.location}</span>
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>

            {/* Profile Section */}
            {trainerInfo && (
              <div className="profile-section">
                <div className="profile-card">
                  <h3>Your Profile</h3>
                  <div className="profile-info">
                    <div className="profile-image-wrapper">
                      <img 
                        src={trainerInfo.profilePicture || coachDefaultImage} 
                        alt="Profile" 
                        className="profile-image" 
                      />
                    </div>
                    <div className="profile-details">
                      {isEditing ? (
                        <div className="edit-form">
                          <div className="form-group">
                            <label>Name:</label>
                            <input 
                              type="text" 
                              name="name" 
                              value={formData.name} 
                              onChange={handleChange} 
                            />
                          </div>
                          <div className="form-group">
                            <label>Email:</label>
                            <input 
                              type="email" 
                              name="email" 
                              value={formData.email} 
                              onChange={handleChange} 
                            />
                          </div>
                          <div className="form-group">
                            <label>Experience (years):</label>
                            <input 
                              type="number" 
                              name="experience" 
                              value={formData.experience} 
                              onChange={handleChange} 
                              min="0"
                            />
                          </div>
                        </div>
                      ) : (
                        <>
                          <p><strong>Name:</strong> {trainerInfo.name}</p>
                          <p><strong>Email:</strong> {trainerInfo.email}</p>
                          <p><strong>Experience:</strong> {trainerInfo.experience} years</p>
                        </>
                      )}
                    </div>
                  </div>
                  <div className="profile-actions">
                    <button className="edit-profile-button" onClick={toggleEdit}>
                      {isEditing ? 'Save Changes' : 'Edit Profile'}
                    </button>
                    <button className="delete-profile-button" onClick={deleteProfile}>
                      Delete Profile
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Edit Coach Modal */}
      {editingCoach && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Edit Coach</h3>
            <div className="edit-coach-form">
              <div className="form-group">
                <label>Name:</label>
                <input 
                  type="text" 
                  name="name" 
                  value={editingCoach.name} 
                  onChange={handleCoachChange} 
                />
              </div>
              <div className="form-group">
                <label>Email:</label>
                <input 
                  type="email" 
                  name="email" 
                  value={editingCoach.email} 
                  onChange={handleCoachChange} 
                />
              </div>
              <div className="form-group">
                <label>Experience (years):</label>
                <input 
                  type="number" 
                  name="experience" 
                  value={editingCoach.experience || ''} 
                  onChange={handleCoachChange} 
                  min="0"
                />
              </div>
              <div className="modal-actions">
                <button onClick={saveCoach} className="save-btn">Save</button>
                <button onClick={cancelEditCoach} className="cancel-btn">Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;
